CREATE TABLE IF NOT EXISTS resumes(id INTEGER PRIMARY KEY,filename TEXT NOT NULL,raw_text TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS targets(id INTEGER PRIMARY KEY,type TEXT NOT NULL,name TEXT NOT NULL,jd_text TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS analyses(id INTEGER PRIMARY KEY,resume_id INTEGER NOT NULL REFERENCES resumes(id),target_id INTEGER NOT NULL REFERENCES targets(id),overall_score REAL NOT NULL,score_breakdown_json TEXT NOT NULL,profile_json TEXT NOT NULL,recommendations_json TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS analysis_skills(id INTEGER PRIMARY KEY,analysis_id INTEGER NOT NULL REFERENCES analyses(id) ON DELETE CASCADE,skill TEXT NOT NULL,status TEXT NOT NULL,confidence REAL NOT NULL,category TEXT NOT NULL,required INTEGER DEFAULT 1);
